 '/platform':{'PF02':'E03','PF01-MAP':'E03','PF05-INFRA':'PF05','technical-foundation':'PF05','E01':'E03','E02':'E03','E05':'E03','E06':'PF04'},
 '/platform/conative-engine':{'E01':'E03','E02':'E03','E05':'E03'},
 '/banking':{'B03':'B02','B04':'B02','B05':'B02','B06':'B02','journey-card':'journey-credit-cards','journey-mortgage':'journey-mortgage-guidance'},
