const LEGACY_CASES={'deposits':'deposits','card':'credit-cards','mortgage':'mortgage-guidance','lihi':'account-opening'};
let contactContext={interest:'',journey:''};
function applyContactContext(r,params){
 const selected=params.get('section')||'';
 if(r==='/banking')contactContext={interest:'Banking',journey:selected.startsWith('journey-')?selected.slice(8):''};
 else if(r==='/health')contactContext={interest:'Health',journey:selected.startsWith('journey-')?selected.slice(8):''};
 if(['/contact','/demo'].includes(r)&&params.get('interest'))contactContext={interest:params.get('interest'),journey:params.get('journey')||''};
 const select=document.getElementById('contact-interest');if(select&&contactContext.interest&&[...select.options].some(o=>o.value===contactContext.interest))select.value=contactContext.interest;
 for(const a of document.querySelectorAll('a[href^="#/contact"],a[href^="#/demo"]')){const original=a.dataset.contactBase||a.getAttribute('href');a.dataset.contactBase=original;if(['#/contact','#/demo'].includes(original)&&contactContext.interest){const q=new URLSearchParams({interest:contactContext.interest});if(contactContext.journey)q.set('journey',contactContext.journey);a.href=original+'?'+q;}}
}
function route(){
 let raw=location.hash.slice(1)||'/';let [r,q='']=raw.split('?');let params=new URLSearchParams(q);
 if(r==='/platform/conative-engine'||r==='/conative-ai'){
  const prior=params.get('section')||'E03';
  const target=({'E01':'E03','E02':'E03','E05':'E03','E06':'PF04'})[prior]||prior;
  params.set('section',target);location.replace('#/platform?'+params);return;
 }
 if(ALIASES[r]){location.replace('#'+ALIASES[r]);return;}
 if(r==='/health'&&(params.has('health')||(params.get('section')||'').startsWith('HC'))){params=new URLSearchParams({section:'journey-menopause'});location.replace('#/health?'+params);return;}
 if(r==='/banking'&&params.has('case')){params=new URLSearchParams({section:'journey-'+(LEGACY_CASES[params.get('case')]||'account-opening')});location.replace('#/banking?'+params);return;}
 const old=params.get('section');if(OLD_SECTIONS[r]?.[old]){params.set('section',OLD_SECTIONS[r][old]);location.replace('#'+r+'?'+params);return;}
 const page=pages.get(r);if(!page){main.innerHTML='<section class="hero"><div class="wrap"><h1>Page not found.</h1><p><a href="#/">Return home</a></p></div></section>';return;}
 document.title=r==='/'?'Lybi · Conative AI':'Lybi · '+page.name;document.querySelector('meta[name=description]').content=page.description;
 main.innerHTML=page.html;
 document.querySelectorAll('.primary-nav details').forEach(d=>d.open=false);document.querySelector('.primary-nav').classList.remove('mobile-open');document.getElementById('mobile-menu').setAttribute('aria-expanded','false');
 for(const a of document.querySelectorAll('.primary-nav a')){if(a.hash==='#'+r)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}
 document.querySelectorAll('dialog[open]').forEach(d=>d.close());applyContactContext(r,params);
 requestAnimationFrame(()=>{const target=params.get('section')&&document.getElementById(params.get('section'));if(target){if(target.tagName==='DETAILS')target.open=true;for(let p=target.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;target.scrollIntoView({behavior:'instant',block:'start'});}else{window.scrollTo({top:0,behavior:'instant'});main.querySelector('h1')?.focus({preventScroll:true});}});
}
function initDialogs(){
 document.getElementById('map-body').innerHTML='<p>Platform brings the Conative Engine and shared capabilities together, followed by domain expertise and ready Decision Journeys. Banking and Health remain separate journey catalogues.</p><div class="sitemap-grid">'+DATA.pages.map(p=>`<a href="#${p.route}"><strong>${escapeHTML(p.name)}</strong><span>${escapeHTML(p.description)}</span></a>`).join('')+'</div>';
 document.getElementById('film-body').innerHTML='<p>Proposed storyboard. The film has not been produced.</p><div class="actions"><button class="button secondary" data-download-film type="button">Download the film brief ↗</button></div><div class="film-scenes">'+DATA.film.map((s,i)=>`<article class="film-scene"><div class="film-scene-heading"><h3>${i+1}. ${escapeHTML(s.title)}</h3><span>${escapeHTML(s.time)}</span></div><div class="film-scene-body"><div><strong>VOICE-OVER</strong><p>${escapeHTML(s.vo.replace(/—/g,', '))}</p></div><div><strong>VISUAL DIRECTION</strong><p>${escapeHTML(s.visual.replace(/—/g,', '))}</p></div></div></article>`).join('')+'</div>';
}
