const PERSONAL_DOMAINS=new Set(['gmail.com','googlemail.com','yahoo.com','yahoo.co.uk','yahoo.co.il','yahoo.fr','ymail.com','rocketmail.com','hotmail.com','hotmail.co.uk','hotmail.co.il','outlook.com','outlook.co.il','live.com','live.co.uk','msn.com','icloud.com','me.com','mac.com','aol.com','proton.me','protonmail.com','pm.me','gmx.com','gmx.de','mail.com','fastmail.com','yandex.com','yandex.ru','mail.ru','qq.com','163.com','126.com','walla.co.il','walla.com','nana.co.il','012.net.il','013.net.il','netvision.net.il','bezeqint.net']);
function validateWorkEmail(raw){
 const email=String(raw||'').trim();if(email.length>254||!email||/\s/.test(email))return {ok:false,error:'Please enter a valid work email address.'};
 const m=email.match(/^([A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+)@([A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?)$/);
 if(!m||m[1].length>64||m[1].startsWith('.')||m[1].endsWith('.')||m[1].includes('..'))return {ok:false,error:'Please enter a valid work email address.'};
 const domain=m[2].toLowerCase(),labels=domain.split('.');if(labels.length<2||labels.some(l=>!l||l.length>63||l.startsWith('-')||l.endsWith('-'))||!/[a-z]/i.test(labels.at(-1))||labels.at(-1).length<2)return {ok:false,error:'Please enter a valid work email address.'};
 if([...PERSONAL_DOMAINS].some(d=>domain===d||domain.endsWith('.'+d)))return {ok:false,error:'Please use your organization’s email address, not a personal email provider.'};
 return {ok:true,email};
}
document.addEventListener('click',e=>{
 const skip=e.target.closest('.skip-link');if(skip){e.preventDefault();main.scrollIntoView();main.querySelector('h1')?.focus();return;}
 const b=e.target.closest('button');if(b){
  const ids={'mobile-menu':()=>{const n=document.querySelector('.primary-nav');b.setAttribute('aria-expanded',String(n.classList.toggle('mobile-open')));}};
  if(ids[b.id]){ids[b.id]();return;}
  if(b.hasAttribute('data-open-film'))showDialog('film-dialog');
  if(b.hasAttribute('data-open-map'))showDialog('map-dialog');
  if(b.hasAttribute('data-close-dialog'))b.closest('dialog').close();
  if(b.hasAttribute('data-download-film'))download('Lybi-Film-Brief-source.md',FILM_MD);
 }
 const a=e.target.closest('a[href^="#/"]');if(a&&a.hash===location.hash){e.preventDefault();route();}
});
