const API=/^(localhost|127\.0\.0\.1)$/.test(location.hostname)?'':'https://aspect-agent-server-1018338671074.europe-west1.run.app';
async function sendContact(payload){
 const r=await fetch(API+'/api/lybi/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
 if(!r.ok)throw new Error('HTTP '+r.status);
}
async function submitForm(form,status,payload,done){
 const button=form.querySelector('button[type=submit]'),label=button.textContent;
 button.disabled=true;button.textContent='Sending…';status.className='';status.textContent='';
 try{await sendContact(payload);form.reset();status.className='form-sent';status.textContent=done;}
 catch(err){status.className='form-error';status.textContent='We couldn’t send this just now. Please try again in a moment.';}
 finally{button.disabled=false;button.textContent=label;}
}
main.addEventListener('submit',e=>{
 if(e.target.id==='demo-form'){e.preventDefault();const input=document.getElementById('demo-email'),s=document.getElementById('demo-status');const v=validateWorkEmail(input.value);input.setAttribute('aria-invalid',String(!v.ok));s.className=v.ok?'demo-valid':'demo-error';if(!v.ok){s.textContent=v.error;input.focus();return;}submitForm(e.target,s,{name:'Demo request',email:v.email,company:v.email.split('@')[1],message:'Demo request from lybi.ai'},'Thank you, we’ll be in touch to arrange your demo.');return;}
 if(e.target.id==='contact-form'){e.preventDefault();const f=e.target,s=document.getElementById('contact-status');let valid=true;f.querySelectorAll('input[required]').forEach(i=>{const ok=!!i.value.trim()&&i.checkValidity();i.setAttribute('aria-invalid',String(!ok));if(!ok)valid=false;});if(!valid){s.className='form-error';s.textContent='Please complete the required fields.';f.querySelector('[aria-invalid="true"]')?.focus();return;}
  const v=n=>f.elements.namedItem(n).value.trim();submitForm(f,s,{name:v('name'),email:v('email'),company:v('organization'),message:[v('role')&&'Role: '+v('role'),v('interest')&&'Area of interest: '+v('interest'),v('message')].filter(Boolean).join(String.fromCharCode(10,10))},'Thank you, we’ll be in touch.');}
});
