/* Keep the definition and all three actions in one uninterrupted reading order. */
window.lybiMountEngine = function(main) {
  const section = main.querySelector('#H05, #E03');
  if (!section || section.querySelector('.engine-animation')) return;
  const brief = section.querySelector('.engine-brief, .engine-loop');
  if (!brief) return;
  const conclusion = brief.querySelector('.brief-feedback, .decision-path-unified');
  if (!conclusion) return;
  const figure = document.createElement('figure');
  figure.className = 'engine-animation';
  const frame = document.createElement('iframe');
  frame.title = 'Conative Engine: interactions update the Live Decision State and shape the Decision Path';
  frame.loading = 'lazy';
  frame.setAttribute('sandbox', 'allow-scripts');
  // A separate cached file — not an inline srcdoc that re-parses megabytes on every visit.
  frame.src = '/lybi-site/engine.html';
  figure.append(frame);
  conclusion.after(figure);
  brief.classList.add('engine-animation-layout');
};

