/* 09-script-09.js */
/* One action system for every route. Keep reviewer anchors and interaction handlers. */
(() => {
  function normalize(root) {
    for (const el of root.querySelectorAll('.button, .quiet-link, .text-link')) {
      if (el.closest('[data-lr-ui]')) continue;
      const label = el.textContent.replace(/\s*↗\s*$/u, '').trim();
      const primary = el.classList.contains('primary') && label !== 'Learn more';
      el.classList.remove('button', 'primary', 'secondary', 'film-button', 'quiet-link', 'text-link');
      el.classList.add(primary ? 'site-action' : 'site-link');
      // Arrows are decoration, not part of the navigation/action meaning.
      for (const icon of el.querySelectorAll('[aria-hidden="true"]')) {
        if (/^[\s↗↓→]*$/u.test(icon.textContent)) icon.remove();
      }
      for (const node of el.childNodes) {
        if (node.nodeType === Node.TEXT_NODE && /↗/u.test(node.textContent)) {
          node.textContent = node.textContent.replace(/\s*↗/gu, '');
        }
      }
    }
  }
  normalize(document);
  // The router replaces main's children; annotation/style changes do not re-run this.
  new MutationObserver(() => normalize(document.getElementById('main')))
    .observe(document.getElementById('main'), {childList:true});
})();

