/* 11-demo.js */
/* Noa's account-opening demo (source/demo/account-opening.html, 2026-10-19), shown on
   Home (between Decision Journeys and Lybi Platform) and Platform (between the Conative
   Engine and Platform capabilities). It plays from the start, so it only loads once a
   visitor actually reaches it — not while it is still off screen. */
(function(){
"use strict";
var main=document.getElementById('main');if(!main)return;
var io='IntersectionObserver' in window?new IntersectionObserver(function(es){es.forEach(function(e){
  if(!e.isIntersecting)return;var f=e.target;f.src=f.getAttribute('data-demo-src');f.removeAttribute('data-demo-src');io.unobserve(f);
});},{threshold:.35}):null;
function wire(){main.querySelectorAll('iframe[data-demo-src]').forEach(function(f){if(io)io.observe(f);else f.src=f.getAttribute('data-demo-src');});}
new MutationObserver(wire).observe(main,{childList:true});wire();
})();
